"""Mutalia-e-Quran XII PDF83: p.80 — verses 5:103 (begun on p.79)–106 (5:107 continues onto p.81; recorded there). Run: python class12_quran_page083.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p83():
    b = Builder()
    V(b, 5, 103, 'اللہ نے (جانوروں میں) نہ کوئی بحیرہ مقرر کیا اور نہ سائبہ اور نہ وصیلہ اور نہ حام لیکن وہ لوگ جنھوں نے کفر کیا وہ اللہ پر جھوٹ باندھتے ہیں اور ان میں سے اکثر لوگ سمجھتے نہیں۔',
      'الله په (څارویو کې) نه کوم بحیره ټاکلی او نه سائبه او نه وصیله او نه حام؛ خو هغه کسان چې کفر یې کړی، پر الله درواغ تړي، او د هغوی ډېری نه پوهېږي.')
    V(b, 5, 104, 'اور جب اُن سے کہا جاتا ہے کہ آؤ اُس (قرآن) کی طرف جو اللہ نے نازل فرمایا ہے اور رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی طرف تو وہ کہتے ہیں ہمارے لیے وہی کافی ہے جس پر ہم نے اپنے باپ دادا کو پایا (بھلا) اگرچہ اُن کے باپ دادا نہ کچھ جانتے ہوں اور نہ ہدایت یافتہ ہوں (کیا پھر بھی ان کی پیروی کریں گے؟)',
      'او کله چې ورته وویل شي: «هغه (قرآن) ته راشئ چې الله نازل کړی او رسول (صلی الله علیه وعلی آله واصحابه وسلم) ته»، وایي: «موږ ته هماغه بس دی چې خپل پلرونه مو پرې موندلي.» (ایا) که څه هم د هغوی پلرونه نه څه پوهېدل او نه هدایت موندلي وو، (بیا هم به یې پیروي کوي؟)')
    V(b, 5, 105, 'اے ایمان والو! تم پر اپنی جانوں کی ذمہ داری ہے تمھیں نقصان نہیں دے سکتا جو گم راہ ہوا جب کہ تم (خود) ہدایت پر ہو اللہ (ہی) کی طرف تمھیں واپس جانا ہے پھر وہ تمھیں بتا دے گا جو کچھ تم کیا کرتے تھے۔',
      'ای مؤمنانو! پر تاسو د خپلو ځانونو مسؤلیت دی؛ څوک چې ګمراه شو، تاسو ته زیان نه شي رسولی کله چې تاسو (پخپله) پر هدایت یاست؛ (یوازې) الله ته مو بېرته ورتلل دي، بیا به تاسو ته وښیي چې څه مو کول.')
    V(b, 5, 106, 'اے ایمان والو! تمھارے درمیان گواہی کا معاملہ اس طرح ہو کہ جب تم میں سے کسی کی موت قریب آ جائے وصیت کرتے وقت تم میں سے دو معتبر شخص ہوں (جو تمھاری وصیت پر گواہ بنیں) یا تمھارے غیروں (غیر مسلموں) میں سے دوسرے دو ہوں اگر تم زمین میں سفر کر رہے ہو پھر تمھیں موت کی مصیبت آ پہنچے ان دونوں کو نماز کے بعد روک لو اگر تمھیں شک پڑ جائے تو وہ اللہ کی قسم اٹھائیں کہ ہم اس (گواہی) کے عوض کوئی مال نہیں لیں گے اگرچہ کوئی قریبی رشتہ دار ہی کیوں نہ ہو اور ہم اللہ کی گواہی کو نہیں چھپائیں گے (اگر ہم ایسا کریں) تو یقیناً ہم گناہ گاروں میں سے ہوں گے۔',
      'ای مؤمنانو! ستاسو ترمنځ د شاهدۍ چاره دې داسې وي: کله چې له تاسو کوم یوه ته مرګ نږدې شي، د وصیت پر مهال دې له تاسو دوه معتبر کسان وي (چې ستاسو پر وصیت شاهدان شي)، یا ستاسو له پردیو (غیر مسلمانانو) بل دوه وي، که په ځمکه کې سفر کوئ او د مرګ مصیبت درته راشي؛ دواړه له لمانځه وروسته ودروئ؛ که شک مو وکړ، نو په الله دې قسم وخوري چې «موږ به د دې (شاهدۍ) په بدل کې هېڅ مال وانه خلو، که څه هم نږدې خپلوان وي، او د الله شاهدي به پټه نه کړو؛ (که داسې وکړو) نو یقیناً به له ګناهګارانو یو.»')
    BOOK.save(83, [(8, rec(b, 8, 83, 83))], issues=[{'id': 'mq12-pdf083', 'unit': 8, 'printedPage': 80,
               'description': 'Verse 5:103 (begun on p.79) recorded here; 5:107 begins on the last four lines of p.80 and is recorded with p.81. Ruku sign after verse 105 not reproduced.'}])


